{
  "project": {
    "name": "spring-petclinic",
    "build_system": "maven",
    "java_version": "17",
    "packaging": "jar",
    "final_name": "spring-petclinic"
  },
  "framework": {
    "core": "spring-boot"
  },
  "server": {
    "start_cmd": "./mvnw spring-boot:run",
    "type": "spring-boot",
    "url": "http://localhost:8080"
  },
  "context_path": null,
  "database": {
    "type": "mysql",
    "url": null,
    "username": null,
    "password": null,
    "ddl_files": []
  },
  "wiremock_ports": [],
  "existing_infra": {
    "docker_compose": "docker-compose.yml",
    "dockerfile": null,
    "init_db_dir": null
  },
  "jacoco": {
    "base_package": "org.springframework.data.util",
    "includes": "org.springframework.data.util.*",
    "exec_path": "jacoco-output/jacoco.exec",
    "agent_mount": "/jacoco/jacocoagent.jar",
    "output_mount": "/jacoco-output",
    "env_var": "JAVA_TOOL_OPTIONS",
    "note": "docker-compose에서 app 서비스에 JAVA_TOOL_OPTIONS로 agent 주입, volume으로 exec 파일 추출"
  },
  "otel": {
    "purpose": "병렬 테스트 시 WireMock stub을 W3C baggage(tid)로 격리하기 위한 OTEL Java Agent",
    "agent_version": "2.12.0",
    "agent_source": "https://github.com/open-telemetry/opentelemetry-java-instrumentation/releases/download/v2.12.0/opentelemetry-javaagent.jar",
    "agent_target_path": "target/otel-agent/opentelemetry-javaagent.jar",
    "container_path": "/app/opentelemetry-javaagent.jar",
    "javaagent_option": "-javaagent:/app/opentelemetry-javaagent.jar",
    "env": {
      "OTEL_TRACES_EXPORTER": "none",
      "OTEL_METRICS_EXPORTER": "none",
      "OTEL_LOGS_EXPORTER": "none",
      "OTEL_PROPAGATORS": "tracecontext,baggage"
    },
    "note": "Dockerfile에서 COPY로 이미지에 포함하고, docker-compose app 서비스 JAVA_TOOL_OPTIONS에 -javaagent로 주입한다. exporter는 none(테스트 전용), baggage propagator로 tid를 외부 연동 호출에 전파한다(test-generation.md Step 3-C 참조)."
  },
  "docker_compose": {
    "files_to_generate": [
      "docker/Dockerfile",
      "docker/docker-compose.yml",
      "docker/docker-compose.coverage.yml",
      "docker/init-db/"
    ],
    "services": [
      "app",
      "mysql",
      "wiremock"
    ],
    "note": "모든 서비스를 docker-compose로 관리. app은 Dockerfile로 빌드한다. app 서비스에는 OTEL Java Agent(-javaagent) + OTEL_* env를 포함하고, coverage override(docker-compose.coverage.yml)에서는 OTEL + JaCoCo 이중 agent를 주입한다."
  },
  "analysis_meta": {
    "timestamp": "2026-07-17T10:19:19Z"
  }
}

