1	package org.springframework.samples.petclinic.security.blackbox;
2	
3	import static org.springframework.samples.petclinic.security.blackbox.support.BlackBoxSupport.BASE_URL;
4	import static org.springframework.samples.petclinic.security.blackbox.support.BlackBoxSupport.executeSqlTemplate;
5	import static org.springframework.samples.petclinic.security.blackbox.support.BlackBoxSupport.testId;
6	import static org.springframework.samples.petclinic.security.blackbox.support.BlackBoxSupport.testSeq;
7	import static io.restassured.RestAssured.given;
8	import static org.hamcrest.Matchers.containsString;
9	import static org.hamcrest.Matchers.equalTo;
10	import static org.hamcrest.Matchers.notNullValue;
11	
12	import java.util.Map;
13	
14	import org.junit.jupiter.api.Test;
15	import org.junit.jupiter.api.TestInfo;
16	import org.junit.jupiter.api.TestInstance;
17	import org.junit.jupiter.api.parallel.Execution;
18	import org.junit.jupiter.api.parallel.ExecutionMode;
19	
20	import io.restassured.http.ContentType;
21	
22	/**
23	 * Black-Box API Integration Test (template-rendered v2)
24	 *
25	 * @target-controller AuthController (src/main/java/org/springframework/samples/petclinic/security/AuthController.java)
26	 * @target-api POST /api/auth/login
27	 *
28	 * JWT-based authentication endpoint
29	 * Requires valid username/password in LoginRequest
30	 * Returns JWT token on success, error message on failure
31	 */
32	@TestInstance(TestInstance.Lifecycle.PER_METHOD)
33	@Execution(ExecutionMode.CONCURRENT)
34	class AuthLoginBlackBoxTest {
35	
36	    private Map<String, String> seed(TestInfo info) {
37	        return Map.of(
38	                "USER_ID", "user" + testId(info),
39	                "USERNAME", "testuser");
40	    }
41	
42	    private void arrange(Map<String, String> p) {
43	        executeSqlTemplate("sql/api-auth-login-teardown.sql", p);
44	        executeSqlTemplate("sql/api-auth-login-setup.sql", p);
45	    }
46	
47	    @Test
48	    void NTC_login_success(TestInfo info) {
49	        Map<String, String> p = seed(info);
50	        arrange(p);
51	        try {
52	            given().baseUri(BASE_URL)
53	                    .contentType(ContentType.JSON)
54	                    .body("{\"username\": \"" + p.get("USERNAME") + "\", \"password\": \"password123\"}")
55	            .when()
56	                    .post("/api/auth/login")
57	            .then()
58	                    .statusCode(200)
59	                    .body("token", notNullValue())
60	                    .body("type", equalTo("Bearer"))
61	                    .body("username", equalTo("${USERNAME}"))
62	                    .body("expiresIn", equalTo(86400));
63	        } finally {
64	            executeSqlTemplate("sql/api-auth-login-teardown.sql", p);
65	        }
66	    }
67	
68	    @Test
