package org.springframework.samples.petclinic.security.blackbox;

import static org.springframework.samples.petclinic.security.blackbox.support.BlackBoxSupport.BASE_URL;
import static org.springframework.samples.petclinic.security.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static org.springframework.samples.petclinic.security.blackbox.support.BlackBoxSupport.testId;
import static org.springframework.samples.petclinic.security.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.containsString;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller AuthController (src/main/java/org/springframework/samples/petclinic/security/AuthController.java)
 * @target-api POST /api/auth/login
 *
 * JWT-based authentication endpoint
 * Requires valid username/password in LoginRequest
 * Returns JWT token on success, error message on failure
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthLoginBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "USER_ID", "user" + testId(info),
                "USERNAME", "testuser");
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/api-auth-login-teardown.sql", p);
        executeSqlTemplate("sql/api-auth-login-setup.sql", p);
    }

    @Test
    void NTC_login_success(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"username\": \"" + p.get("USERNAME") + "\", \"password\": \"password123\"}")
            .when()
                    .post("/api/auth/login")
            .then()
                    .statusCode(200)
                    .body("token", notNullValue())
                    .body("type", equalTo("Bearer"))
                    .body("username", equalTo("${USERNAME}"))
                    .body("expiresIn", equalTo(86400));
        } finally {
            executeSqlTemplate("sql/api-auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_username_NULL(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"username\": null, \"password\": \"password123\"}")
            .when()
                    .post("/api/auth/login")
            .then()
                    .statusCode(400)
                    .body("error", notNullValue());
        } finally {
            executeSqlTemplate("sql/api-auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_username_EMPTY(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"username\": \"\", \"password\": \"password123\"}")
            .when()
                    .post("/api/auth/login")
            .then()
                    .statusCode(400)
                    .body("error", notNullValue());
        } finally {
            executeSqlTemplate("sql/api-auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_password_EMPTY(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"username\": \"" + p.get("USERNAME") + "\", \"password\": \"\"}")
            .when()
                    .post("/api/auth/login")
            .then()
                    .statusCode(400)
                    .body("error", notNullValue());
        } finally {
            executeSqlTemplate("sql/api-auth-login-teardown.sql", p);
        }
    }

    @Test
    void ATC_invalid_credentials(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"username\": \"nonexistent\", \"password\": \"wrongpassword\"}")
            .when()
                    .post("/api/auth/login")
            .then()
                    .statusCode(400)
                    .body("error", containsString("Invalid"));
        } finally {
            executeSqlTemplate("sql/api-auth-login-teardown.sql", p);
        }
    }
}

