    void NTC_createOwner_success(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer test-token-fixture")
                    .contentType(ContentType.JSON)
